import yaml
with open('registry.yaml') as f:
    reg = yaml.safe_load(f)

# Get all MATH-500 experiments that are DONE with success
math500_done = {}
for eid, exp in reg.items():
    if 'math500' in eid.lower() and exp.get('status') == 'DONE' and exp.get('conclusion') == 'success':
        m = exp.get('metrics', {})
        if m.get('accuracy') is not None:
            math500_done[eid] = {
                'accuracy': m['accuracy'],
                'stderr': m.get('stderr'),
                'correct': m.get('correct'),
                'total': m.get('total'),
            }

for eid, d in sorted(math500_done.items()):
    print(f'{eid}: acc={d[\"accuracy\"]:.3f} ±{d.get(\"stderr\",0):.4f} ({d.get(\"correct\")}/{d.get(\"total\")})')
"

